class Solution { public int numFriendRequests(int[] ages){int[] count=new int[121];for(int age:ages)count[age]++;int answer=0;for(int sender=1;sender<=120;sender++)for(int receiver=1;receiver<=120;receiver++){if(count[sender]==0||count[receiver]==0||2*receiver<=sender+14||receiver>sender||receiver>100&&sender<100)continue;answer+=count[sender]*count[receiver]-(sender==receiver?count[sender]:0);}return answer;} }
